"""Offline card rendering against discovery/state generated by the actual module."""
from dataclasses import dataclass
from datetime import datetime, timezone
import json
from pathlib import Path
import unittest

try:
    import yaml
    from jinja2 import StrictUndefined
    from jinja2.nativetypes import NativeEnvironment
except ImportError:
    yaml = NativeEnvironment = None

from rclone_multithreaded_upload import ha_live_preview as h


@dataclass
class Entity:
    entity_id: str
    name: str
    state: str
    attributes: dict
    device: str


class FakeHA:
    def __init__(self):
        self.entities = {}
        self.devices = {}

    @property
    def sensor(self):
        return list(self.entities.values())

    def __call__(self, entity_id):
        return self.entities[entity_id].state if entity_id in self.entities else 'unknown'

    def state_attr(self, entity_id, key):
        return self.entities[entity_id].attributes.get(key) if entity_id in self.entities else None

    def device_id(self, entity_id):
        return self.entities[entity_id].device if entity_id in self.entities else None

    def device_attr(self, value, key):
        device = self.device_id(value) or value
        return self.devices.get(device, {}).get(key)

    def device_entities(self, device):
        return [eid for eid, item in self.entities.items() if item.device == device]


@unittest.skipIf(NativeEnvironment is None, 'Card rendering needs optional requirements-test.txt')
class CardTests(unittest.TestCase):
    def setUp(self):
        self.env = NativeEnvironment(undefined=StrictUndefined)
        def ha_bool(value, default=False):
            if isinstance(value, str):
                if value.lower() in ('true', 'yes', 'on', '1'):
                    return True
                if value.lower() in ('false', 'no', 'off', '0'):
                    return False
                return default
            return bool(value) if value is not None else default
        self.env.filters['bool'] = ha_bool
        self.ha = FakeHA()
        self.content = (Path(__file__).resolve().parents[1] / 'manufacturer-live-preview-card.md').read_text()

    def state(self, outcome='running', run_id='current', unknown=False):
        live = h.LivePreview(h.LiveConfig(), name='NAS backup', job='backup', run_id=run_id)
        live.start()
        if not unknown:
            live.update(total=4, completed=3, current_item='pool/current', phase='sending',
                        transferred_bytes=1073741824, bytes_per_second=1048576)
        if outcome == 'failure':
            live.record_dataset('success', source='pool/a', destination='backup/a')
            live.record_dataset('failure', source='pool/b', destination='backup/b', reason='Out of space')
            live.record_dataset('skipped', source='pool/c', destination='backup/c', reason='Already present')
            live.finish(12, error='Receive failed', stderr='cannot receive: out of space <unsafe>')
        elif outcome == 'success':
            live.update(total=4, completed=4)
            live.finish(0)
        elif outcome == 'incomplete':
            live.finish(0, incomplete=True)
        elif outcome == 'interrupted':
            live.finish(130, interrupted=True)
        return live.snapshot()

    def add(self, identity, name='NAS backup', *, live=None, last=None,
            manufacturer='rclone-multithreaded-upload', expired=False, renamed=False):
        config = h.LiveConfig(device_id=identity, manufacturer=manufacturer)
        device = 'device_' + identity
        self.ha.devices[device] = {'manufacturer': manufacturer, 'name': name}
        for index, item in enumerate(h.discovery_messages(config, name)):
            spec = item['payload']
            payload = last if spec['state_topic'] == config.result_topic else live
            eid = f'sensor.renamed_{identity}_{index}' if renamed else spec['default_entity_id']
            label = f'Renamed field {index}' if renamed else name + ' ' + spec['name']
            attributes = {'friendly_name': label}
            value = 'unknown'
            if payload is not None:
                raw = self.env.from_string(spec['value_template']).render(value_json=payload)
                value = str(raw) if raw is not None else 'unknown'
                if 'json_attributes_template' in spec:
                    data = self.env.from_string(spec['json_attributes_template']).render(value_json=payload)
                    attributes.update(json.loads(data) if isinstance(data, str) else data)
            if expired and spec['state_topic'] == config.state_topic:
                value = 'unavailable'
            self.ha.entities[eid] = Entity(eid, label, value, attributes, device)

    def render(self, manufacturer=None):
        content = self.content
        if manufacturer is not None:
            content = content.replace("{% set manufacturer = 'rclone-multithreaded-upload' %}",
                                      '{% set manufacturer = ' + repr(manufacturer) + ' %}')
        def as_datetime(value, default=None):
            try:
                return datetime.fromisoformat(value.replace('Z', '+00:00'))
            except (ValueError, TypeError, AttributeError):
                return default
        return str(self.env.from_string(content).render(
            states=self.ha, state_attr=self.ha.state_attr, device_id=self.ha.device_id,
            device_attr=self.ha.device_attr, device_entities=self.ha.device_entities,
            as_datetime=as_datetime, as_local=lambda value: value.astimezone(timezone.utc)))

    def test_yaml_wrapper_preserves_markdown_content(self):
        card = yaml.safe_load((Path(__file__).resolve().parents[1] / 'manufacturer-live-preview-card.yaml').read_text())
        self.assertEqual(card['type'], 'markdown')
        self.assertEqual(card['content'], self.content)

    def test_manufacturer_filter_and_custom_name(self):
        self.add('one', name='Custom manufacturer job', live=self.state(), manufacturer='My Backup Jobs')
        self.add('other', name='Other manufacturer job', live=self.state(), manufacturer='Other')
        self.assertIn('No matching live-preview devices', self.render())
        text = self.render('My Backup Jobs')
        self.assertIn('Custom manufacturer job', text)
        self.assertNotIn('Other manufacturer job', text)
        self.assertIn('**1 job(s) discovered**', text)

    def test_devices_added_automatically_and_deduplicated(self):
        self.add('one', name='First job', live=self.state())
        self.assertIn('**1 job(s) discovered**', self.render())
        self.add('two', name='Second job', live=self.state('success'), last=self.state('success'))
        text = self.render()
        self.assertIn('**2 job(s) discovered**', text)
        self.assertEqual(text.count('First job — RUNNING'), 1)
        self.assertEqual(text.count('Second job — SUCCESS'), 1)

    def test_running_metrics_use_current_state_over_previous_result(self):
        self.add('one', live=self.state(), last=self.state('success', run_id='old'))
        text = self.render()
        self.assertIn('— RUNNING', text)
        self.assertIn('pool/current', text)
        self.assertIn('75.0%', text)
        self.assertIn('**Items:** 3 / 4 completed', text)
        self.assertIn('1.00 GiB', text)
        self.assertIn('**Current speed:** 1.00 MiB/s', text)

    def test_expired_terminal_state_uses_retained_result(self):
        state = self.state('success')
        self.add('one', live=state, last=state, expired=True)
        text = self.render()
        self.assertIn('— SUCCESS', text)
        self.assertIn('100%', text.replace('100.0%', '100%'))
        self.assertIn('**Exit code:** 0', text)

    def test_newer_run_with_lost_heartbeat_does_not_claim_old_success(self):
        self.add('one', live=self.state(run_id='new'), last=self.state('success', run_id='old'), expired=True)
        text = self.render()
        self.assertIn('— HEARTBEAT LOST', text)
        self.assertIn('Its outcome is unknown', text)
        self.assertNotIn('— SUCCESS', text)

    def test_first_run_without_retained_result_is_visible(self):
        self.add('one', live=self.state())
        text = self.render()
        self.assertIn('— RUNNING', text)
        self.assertIn('**1 job(s) discovered**', text)

    def test_incomplete_and_interrupted_are_explicit(self):
        for outcome in ('incomplete', 'interrupted'):
            with self.subTest(outcome=outcome):
                self.ha = FakeHA()
                state = self.state(outcome)
                self.add('one', live=state, last=state)
                self.assertIn('— ' + outcome.upper(), self.render())

    def test_unknown_progress_stays_unknown(self):
        self.add('one', live=self.state(unknown=True))
        text = self.render()
        self.assertIn('**Progress:** Unknown', text)
        self.assertIn('**Items:** ? / ? completed', text)
        self.assertNotIn('**0.0%**', text)

    def test_dataset_results_and_stderr_are_formatted(self):
        state = self.state('failure')
        self.add('one', live=state, last=state)
        text = self.render()
        self.assertIn('**Remotes:** 1 successful · 1 failed · 1 skipped', text)
        self.assertIn('- pool/a → backup/a', text)
        self.assertIn('- pool/b → backup/b: Out of space', text)
        self.assertIn('- pool/c → backup/c: Already present', text)
        self.assertIn('cannot receive: out of space &lt;unsafe&gt;', text)
        self.assertNotIn('<unsafe>', text)

    def test_renamed_entities_use_role_markers(self):
        state = self.state('failure')
        self.add('one', live=state, last=state, renamed=True)
        text = self.render()
        self.assertIn('— FAILURE', text)
        self.assertIn('**Exit code:** 12', text)
        self.assertIn('75.0%', text)

    def test_actual_rclone_adapter_fields_autofill_with_renamed_entities(self):
        from test_logic import StateSnapshot
        from rclone_multithreaded_upload.config import parse_live_config
        from rclone_multithreaded_upload.models import UploadDirectory
        from rclone_multithreaded_upload.results import initialize_run_results, record_stage_success, record_stage_failure
        from rclone_multithreaded_upload.reporting import refresh_live
        from rclone_multithreaded_upload.state import STATE
        for failed in (False, True):
            with self.subTest(failed=failed), StateSnapshot():
                self.ha = FakeHA()
                STATE.upload_directories = [UploadDirectory('/srv/cameras', 'cloud:archive', [], [], name='Camera cloud archive')]
                initialize_run_results()
                config = parse_live_config({}, Path('/tmp/rclone.json'))
                live = h.LivePreview(config, name='Camera cloud archive', job='rclone-multithreaded-upload', run_id='real-adapter')
                STATE.live_preview = live
                live.start()
                live.update(phase='reservation_and_upload', current_item='cloud:archive')
                from rclone_multithreaded_upload.progress import step
                with step('cloud:archive', 'pre_snapshot'):
                    pass
                record_stage_success('cloud:archive', 'reservation')
                running = live.snapshot()
                self.add('camera', name='Camera cloud archive', live=running, renamed=True)
                rendered = self.render()
                self.assertIn('Camera cloud archive — RUNNING', rendered)
                self.assertIn('**Steps:** 1 / 10 settled', rendered)
                self.assertIn('10.0%', rendered)
                self.assertIn('**Current:** Waiting for the next phase', rendered)
                if failed:
                    record_stage_failure('cloud:archive', 'upload', 'Rclone quota failed')
                else:
                    record_stage_success('cloud:archive', 'upload')
                for stage in ('post_cleanup', 'final_quota'):
                    record_stage_success('cloud:archive', stage)
                for key in STATE.run_results['cloud:archive'].steps:
                    with step('cloud:archive', key):
                        pass
                refresh_live()
                live.finish(1 if failed else 0, error='Rclone quota failed' if failed else '')
                final = live.snapshot()
                self.ha = FakeHA()
                self.add('camera', name='Camera cloud archive', live=final, last=final, expired=True, renamed=True)
                rendered = self.render()
                self.assertIn('— FAILURE' if failed else '— SUCCESS', rendered)
                self.assertIn('**Steps:** 10 / 10 settled', rendered)
                self.assertIn('/srv/cameras → cloud:archive', rendered)
                self.assertIn('**Transferred:** Unknown', rendered)
                self.assertIn('**Exit code:** 1' if failed else '**Exit code:** 0', rendered)
                live.close()

    def test_completion_automation_accepts_rclone_reports_and_rejects_inconsistent_json(self):
        from test_logic import StateSnapshot
        from rclone_multithreaded_upload.models import UploadDirectory
        from rclone_multithreaded_upload.results import initialize_run_results, record_stage_success, record_stage_failure
        from rclone_multithreaded_upload.mqtt import build_result_payload
        from rclone_multithreaded_upload.state import STATE
        automation = yaml.safe_load((Path(__file__).resolve().parents[1] / 'home-assistant-mqtt-automation.example.yaml').read_text())
        conditions = [choice['conditions'][0]['value_template'] for choice in next(action['choose'] for action in automation['actions'] if 'choose' in action)]
        for failed in (False, True):
            with self.subTest(failed=failed), StateSnapshot():
                STATE.run_error = STATE.stderr_tail = ''
                STATE.upload_directories = [UploadDirectory('/tmp', 'cloud:archive', [], [])]
                initialize_run_results()
                for stage in ('reservation', 'upload', 'post_cleanup', 'final_quota'):
                    record_stage_success('cloud:archive', stage)
                if failed:
                    record_stage_failure('cloud:archive', 'upload', 'Upload failed')
                report = build_result_payload(int(failed))
                def matches(payload):
                    return [bool(self.env.from_string(condition).render(report=payload, result_status=payload.get('status', '')))
                            for condition in conditions]
                self.assertEqual(matches(report), [not failed, failed])
                self.assertEqual(matches({**report, 'exit_code': bool(failed)}), [False, False])
                self.assertEqual(matches({**report, 'success': failed}), [False, False])

    def _notification_report(self, failed=False, **overrides):
        from rclone_multithreaded_upload import APPLICATION_NAME, VERSION
        from rclone_multithreaded_upload.mqtt_status import build_report
        values = dict(name='Camera archive upload', job=APPLICATION_NAME, version=VERSION,
                      exit_code=int(failed), error_message='Upload failed' if failed else '',
                      stderr_text='Latest rclone output',
                      extra={'failed_remotes': ['Cloud'] if failed else [], 'remotes': [{'name': 'Cloud'}]})
        values.update(overrides)
        return build_report(**values)

    def _render_notification_actions(self, report):
        from types import SimpleNamespace
        automation = yaml.safe_load((Path(__file__).resolve().parents[1] / 'home-assistant-mqtt-automation.example.yaml').read_text())
        context = {'trigger': SimpleNamespace(payload_json=report, payload=json.dumps(report), topic='homeassistant/rclone-upload/result')}
        def render_value(value):
            if isinstance(value, dict):
                return {key: render_value(child) for key, child in value.items()}
            if isinstance(value, list):
                return [render_value(child) for child in value]
            if isinstance(value, str) and ('{{' in value or '{%' in value):
                return self.env.from_string(value).render(**context)
            return value
        def condition_matches(condition):
            self.assertEqual(condition['condition'], 'template')
            return self.env.filters['bool'](render_value(condition['value_template']))
        for action in automation['actions']:
            if 'variables' in action:
                for key, value in action['variables'].items():
                    context[key] = render_value(value)
            elif 'if' in action and all(condition_matches(c) for c in action['if']):
                self.assertTrue(any('stop' in entry for entry in action['then']))
                return []
            elif 'choose' in action:
                for choice in action['choose']:
                    if all(condition_matches(c) for c in choice['conditions']):
                        return render_value(choice['sequence'])
                return render_value(action.get('default', []))
        self.fail('Notification automation did not select a result branch')

    def test_completion_pushover_success_and_failure_use_template_metadata(self):
        for failed in (False, True):
            with self.subTest(failed=failed):
                actions = self._render_notification_actions(self._notification_report(failed))
                self.assertEqual([row['action'] for row in actions], ['notify.pushover', 'persistent_notification.create'])
                pushover = actions[0]['data']
                self.assertIn('failure' if failed else 'success', pushover['title'])
                self.assertIn('Exit code: ' + str(int(failed)), pushover['message'])
                self.assertIn('Remotes: Cloud', pushover['message'])
                self.assertEqual(pushover['data']['priority'], int(failed))
                self.assertIn('Latest rclone output', pushover['message'])

    def test_completion_pushover_long_output_is_bounded_and_keeps_latest_tail(self):
        stderr = 'old output ' * 3000 + 'LATEST-RCLONE-ERROR'
        report = self._notification_report(True, stderr_text=stderr, error_message='Full error ' * 1000)
        actions = self._render_notification_actions(report)
        pushover, persistent = actions[0]['data'], actions[1]['data']
        self.assertLessEqual(len(pushover['title']), 250)
        self.assertLessEqual(len(pushover['message']), 1024)
        self.assertIn('LATEST-RCLONE-ERROR', pushover['message'])
        self.assertIn('[stderr shortened for Pushover', pushover['message'])
        self.assertIn(report['stderr'], persistent['message'])
        self.assertIn(report['error'], persistent['message'])
        self.assertGreater(len(persistent['message']), 1024)

    def test_completion_pushover_long_unicode_metadata_remains_within_limits(self):
        report = self._notification_report(True, name='ø' * 800, title='Æ' * 900,
                                          job='r' * 900, error_message='E' * 9000,
                                          stderr_text='diagnostic ' * 500)
        report['host'] = 'h' * 900
        report['remotes'] = [{'name': 'Remote' * 1000}]
        report['failed_remotes'] = ['Failure' * 1000]
        action = self._render_notification_actions(report)[0]['data']
        self.assertLessEqual(len(action['title']), 250)
        self.assertLessEqual(len(action['message']), 1024)
        self.assertIn('stderr shortened for Pushover', action['message'])

    def test_completion_dry_runs_stop_before_all_notifications(self):
        for failed in (False, True):
            self.assertEqual(self._render_notification_actions(self._notification_report(failed, dry_run=True)), [])

    def test_completion_inconsistent_or_nonobject_json_never_sends_pushover(self):
        report = self._notification_report(True)
        for invalid in ({**report, 'exit_code': True}, {**report, 'success': True},
                        {**report, 'status': 'running'}, {}, [], 'malformed'):
            with self.subTest(invalid=invalid):
                actions = self._render_notification_actions(invalid)
                self.assertEqual([row['action'] for row in actions], ['persistent_notification.create'])
                self.assertIn('unknown status', actions[0]['data']['title'])

    def test_completion_short_stderr_is_not_marked_as_truncated(self):
        report = self._notification_report(True, stderr_text='Short complete diagnostic')
        message = self._render_notification_actions(report)[0]['data']['message']
        self.assertIn('Short complete diagnostic', message)
        self.assertNotIn('stderr shortened', message)

    def test_empty_registry_shows_setup_instructions(self):
        text = self.render()
        self.assertIn('**0 job(s) discovered**', text)
        self.assertIn('No matching live-preview devices detected', text)


if __name__ == '__main__':
    unittest.main()
